/**
 * JobGist with Care — LIVE data layer (Supabase + FastAPI backend)
 *
 * api.ts keeps its synchronous, cache-based API so the pages don't change.
 * In LIVE mode that cache is filled from Supabase (RLS applies: anon key + user JWT)
 * by `fetchSnapshot()`, and every mutation is written through to Supabase here.
 * AI (worker profile, applicant summaries) is always generated by the backend.
 *
 * LIVE is on when NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY are set.
 */
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { CASE_TYPES_V3 } from '@/types/database';
import type {
  AIApplicantSummary,
  AIWorkerProfile,
  CaregiverCaseSkill,
  CaregiverDetails,
  CaregiverGender,
  CaregiverLocation,
  CaseTypeCode,
  Certificate,
  ComfortLevel,
  ContactDetails,
  FavoriteRow,
  JobPost,
  JobPostCaseNeed,
  JobPostLocation,
  MatchRow,
  NotificationRow,
  Profile,
  UserRole,
} from '@/types/database';
import { approxLatLng } from './geo';

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';
export const API_BASE = (process.env.NEXT_PUBLIC_API_BASE || '').replace(/\/+$/, '');
export const LIVE = Boolean(SUPABASE_URL && SUPABASE_ANON_KEY);

// Seeded demo accounts (created by backend/scripts/seed_demo.py). Public on purpose.
