// Case-type codes: the UI uses 12 codes, the DB vocabulary (case_types) others.
// ---------------------------------------------------------------------------
const FE_TO_DB: Record<CaseTypeCode, string> = {
  bedridden: 'bedridden',
  tube_feeding: 'feeding_tube',
  dementia: 'dementia',
  stroke: 'stroke_rehab',
  post_surgery: 'post_surgery',
  wound_care: 'wound_care',
  hospital_escort: 'hospital_escort',
  general_elderly: 'general_elderly',
  tracheostomy_suction: 'suction',
  physical_therapy: 'physical_therapy',
  diabetes_insulin: 'diabetes_care',
  palliative_care: 'palliative',
  parkinson: 'parkinson',
  oxygen: 'oxygen',
  urinary_catheter: 'urinary_catheter',
  medication: 'medication',
  mobility_assist: 'mobility_assist',
  fall_risk: 'fall_risk',
  bathing_toileting: 'bathing_toileting',
  night_watch: 'night_watch',
  meal_prep: 'meal_prep',
  light_housework: 'light_housework',
};
const DB_TO_FE: Record<string, CaseTypeCode> = Object.fromEntries(
  Object.entries(FE_TO_DB).map(([fe, db]) => [db, fe as CaseTypeCode])
);
export const toDbCase = (c: CaseTypeCode) => FE_TO_DB[c] ?? c;
export const toFeCase = (c: string): CaseTypeCode | null => DB_TO_FE[c] ?? null;

// ---------------------------------------------------------------------------
// Matching score — TypeScript mirror of backend/app/matching/score.py.
// Keep both in sync (weights, credits, thresholds).
// ---------------------------------------------------------------------------
const SPECIALIZED = new Set([
  'bedridden', 'feeding_tube', 'suction', 'dementia', 'parkinson', 'stroke_rehab',
  'wound_care', 'urinary_catheter', 'oxygen', 'diabetes_care', 'palliative',
]);
const WEIGHTS = { specialized: 40, distance: 20, wage: 15, general: 15, experience: 10 };
const LEVEL_CREDIT: Record<string, number> = {
  experienced: 1.0, trained: 0.8, willing_to_learn: 0.2, not_comfortable: 0.0,
};
const DISTANCE_ZERO_KM = 30;
const EXPERIENCE_FULL_YEARS = 5;

export interface ScoreInput {
  needs: CaseTypeCode[];
  jobWageMax: number | null;
  jobWageUnit: string | null;
  distanceKm: number | null;
  skills: { case_type: CaseTypeCode; comfort_level: ComfortLevel }[];
  cgWageMin: number | null;
  cgWageUnit: string | null;
  yearsExperience: number;
  hasVerifiedCert: boolean;
}

export function scoreMatch(i: ScoreInput) {
  const skill: Record<string, string> = {};
  i.skills.forEach((s) => { skill[toDbCase(s.case_type)] = s.comfort_level; });
  const needs = i.needs.map(toDbCase);
  const spec = needs.filter((n) => SPECIALIZED.has(n));
  const gen = needs.filter((n) => !SPECIALIZED.has(n));
  const cov = (list: string[]) =>
    list.length ? list.reduce((a, n) => a + (LEVEL_CREDIT[skill[n] ?? ''] ?? 0), 0) / list.length : 1;

  const specialized = WEIGHTS.specialized * cov(spec);
  const general = WEIGHTS.general * cov(gen);
  const distance = i.distanceKm == null
    ? WEIGHTS.distance / 2
    : WEIGHTS.distance * Math.max(0, 1 - i.distanceKm / DISTANCE_ZERO_KM);

  let wage: number;
  if (i.jobWageMax == null || i.cgWageMin == null || i.jobWageUnit !== i.cgWageUnit) wage = WEIGHTS.wage / 2;
  else if (i.cgWageMin <= i.jobWageMax) wage = WEIGHTS.wage;
  else if (i.cgWageMin <= i.jobWageMax * 1.1) wage = WEIGHTS.wage / 2;
  else wage = 0;

  const years = Math.min(i.yearsExperience || 0, EXPERIENCE_FULL_YEARS);
  const experience = WEIGHTS.experience * (0.6 * years / EXPERIENCE_FULL_YEARS + 0.4 * (i.hasVerifiedCert ? 1 : 0));

  const r1 = (x: number) => Math.round(x * 10) / 10;
  const breakdown = {
    specialized: r1(specialized), distance: r1(distance), wage: r1(wage),
    general: r1(general), experience: r1(experience),
  };
  const missing = (list: string[]) =>
    list.filter((n) => (LEVEL_CREDIT[skill[n] ?? ''] ?? 0) < LEVEL_CREDIT.trained)
      .map(toFeCase).filter((x): x is CaseTypeCode => !!x);
  return {
    total: r1(Object.values(breakdown).reduce((a, b) => a + b, 0)),
    breakdown,
    missing_specialized: missing(spec),
    missing_general: missing(gen),
  };
}

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------
const nowIso = () => new Date().toISOString();
const isUuid = (s?: string | null) =>
  !!s && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);
export const newId = () =>
  typeof crypto !== 'undefined' && 'randomUUID' in crypto
    ? crypto.randomUUID()
    : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
        const r = (Math.random() * 16) | 0;
        return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
      });

const feGender = (g?: string | null): CaregiverGender =>
  g === 'female' || g === 'male' ? g : 'unspecified';
const dbGender = (g?: string | null) =>
  g === 'female' || g === 'male' ? g : g === 'unspecified' ? 'prefer_not_say' : null;
const ageFromBirthYear = (y?: number | null) => (y ? new Date().getFullYear() - y : null);
const birthYearFromAge = (a?: number | null) => {
  if (typeof a !== 'number' || a <= 0) return null;
  const y = new Date().getFullYear() - a;
  return y >= 1940 && y <= 2010 ? y : null;
};
/** Trim, de-duplicate and cap free-text tags before saving (they go into an LLM prompt). */
export const cleanTags = (tags?: string[] | null): string[] =>
  [...new Set((tags || []).map((t) => t.replace(/\s+/g, ' ').trim().slice(0, 30)).filter(Boolean))].slice(0, 8);
const smallAvatar = (u?: string | null) => (u && u.length < 200_000 ? u : null);

function fail(where: string, error: unknown): never {
  const msg = (error as { message?: string })?.message || String(error);
  console.error(`[live] ${where}:`, error);
  throw new Error(`${where}: ${msg}`);
}

async function accessToken(): Promise<string> {
  const { data } = await sb().auth.getSession();
  const t = data.session?.access_token;
  if (!t) throw new Error('ยังไม่ได้เข้าสู่ระบบ');
  return t;
}

async function callBackend<T>(path: string, body?: unknown): Promise<T> {
  if (!API_BASE) throw new Error('NEXT_PUBLIC_API_BASE is not set');
  const res = await fetch(`${API_BASE}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${await accessToken()}` },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`${path} → ${res.status} ${await res.text()}`);
  return res.json() as Promise<T>;
}

// ---------------------------------------------------------------------------
// AUTH
// ---------------------------------------------------------------------------
export interface Me {
  id: string;
  email: string;
  role: UserRole;
  display_name: string;
}

export async function currentMe(): Promise<Me | null> {
  const { data } = await sb().auth.getSession();
  const user = data.session?.user;
  if (!user) return null;
  const { data: prof } = await sb().from('profiles').select('role,display_name').eq('id', user.id).maybeSingle();
  if (!prof) return null;
  return { id: user.id, email: user.email || '', role: prof.role, display_name: prof.display_name };
}

export async function signIn(email: string, password: string): Promise<Me> {
  const { error } = await sb().auth.signInWithPassword({ email: email.trim().toLowerCase(), password });
  if (error) {
    throw new Error(
      /invalid/i.test(error.message) ? 'อีเมลหรือรหัสผ่านไม่ถูกต้อง'
        : /confirm/i.test(error.message) ? 'กรุณายืนยันอีเมลก่อนเข้าสู่ระบบ'
        : error.message
    );
  }
  const me = await currentMe();
  if (!me) throw new Error('ไม่พบโปรไฟล์ของบัญชีนี้');
  return me;
}

export interface PendingSignup {
  email: string;
  password: string;
  display_name: string;
  phone: string;
  line_id?: string | null;
}

export async function signUp(p: PendingSignup, role: UserRole): Promise<Me> {
  const { data, error } = await sb().auth.signUp({
    email: p.email.trim().toLowerCase(),
    password: p.password,
    options: { data: { role, display_name: p.display_name || p.email.split('@')[0], phone: p.phone || null } },
  });
  if (error) {
    throw new Error(/registered/i.test(error.message) ? 'อีเมลนี้มีบัญชีอยู่แล้ว กรุณาเข้าสู่ระบบ' : error.message);
  }
  if (!data.session) {
    throw new Error('สร้างบัญชีแล้ว กรุณายืนยันอีเมลจากกล่องจดหมาย แล้วจึงเข้าสู่ระบบ');
  }
  if (p.line_id) {
    await sb().from('contact_details').update({ line_id: p.line_id }).eq('user_id', data.session.user.id);
  }
  const me = await currentMe();
  if (!me) throw new Error('สร้างโปรไฟล์ไม่สำเร็จ');
  return me;
}

export async function signOut() {
  await sb().auth.signOut();
}

// ---------------------------------------------------------------------------
// SNAPSHOT: everything the signed-in user may see, mapped to UI shapes
// ---------------------------------------------------------------------------
export interface Snapshot {
  me: Me;
  contact: ContactDetails | null;
  profiles: Profile[];
  contacts: Record<string, ContactDetails>;
  caregiverDetails: Record<string, CaregiverDetails>;
  caregiverLocations: Record<string, CaregiverLocation>;
  caregiverSkills: Record<string, CaregiverCaseSkill[]>;
  certificates: Record<string, Certificate[]>;
  jobPosts: JobPost[];
  jobLocations: Record<string, JobPostLocation>;
  jobNeeds: Record<string, JobPostCaseNeed[]>;
  matches: MatchRow[];
  favorites: FavoriteRow[];
  aiProfiles: Record<string, AIWorkerProfile>;
  aiSummaries: Record<string, AIApplicantSummary>;
  notifications: NotificationRow[];
  /** caregiver: job_post_id → km ; family: caregiver_id → km (for the family's job) */
  distances: Record<string, number | null>;
  /** family: caregiver ids returned by candidate_caregivers() for each own open job */
  candidates: Record<string, string[]>;
}

const NOTIF_LINK: Record<string, string> = {
  interest_received: '/family/applicants',
  match: '/matches',
  job_expiring: '/family/profile',
  system: '/',
};

function toWorkerProfile(r: any, override?: string | null): AIWorkerProfile {
  const lines = String(override || r.output_text || '').split('\n').map((l) => l.trim()).filter(Boolean);
  return {
    id: r.id,
    caregiver_id: r.caregiver_id,
    profile_text: override || r.output_text,
    summary_headline: lines[0] || '',
    key_strengths: lines.slice(1, 5).map((l) => l.replace(/^[-•*\d.)\s]+/, '')),
    is_active: r.is_active,
    prompt_version: r.prompt_version,
    input_hash: r.input_hash,
    created_at: r.created_at,
  };
}

const BREAKDOWN_TH: Record<string, string> = {
  specialized: 'ทักษะเฉพาะทางตรงกับเคส',
  distance: 'ระยะทางใกล้',
  wage: 'ค่าจ้างอยู่ในงบ',
  general: 'งานดูแลทั่วไปครบ',
  experience: 'ประสบการณ์/ใบรับรอง',
};

/** Strong points = criteria scoring ≥ 60% of their weight (from the fit-score breakdown). */
export function prosFromBreakdown(b: Record<string, number> = {}): string[] {
  return Object.entries(b)
    .map(([k, v]) => ({ k, v, w: (WEIGHTS as Record<string, number>)[k] || 1 }))
    .filter((x) => x.v / x.w >= 0.6)
    .sort((a, b2) => b2.v / b2.w - a.v / a.w)
    .slice(0, 3)
    .map((x) => `${BREAKDOWN_TH[x.k] || x.k} (${x.v}/${x.w})`);
}

/** Needs the caregiver is not (yet) trained for, as Thai "ask about" points. */
export function toVerifyFromMissing(dbCodes: string[] = []): string[] {
  return dbCodes
    .map(toFeCase).filter((c): c is CaseTypeCode => !!c)
    .map((c) => `ควรสอบถามเรื่อง: ${CASE_TYPES_V3[c].short_label_th}`);
}

function toSummary(r: any): AIApplicantSummary {
  let rationale: any = {};
  try { rationale = typeof r.fit_rationale === 'string' ? JSON.parse(r.fit_rationale) : r.fit_rationale || {}; } catch { /* keep {} */ }
  return {
    id: r.id,
    job_post_id: r.job_post_id,
    caregiver_id: r.caregiver_id,
    summary_text: r.summary_text,
    fit_score: Number(r.fit_score ?? 0),
    fit_rationale: {
      pros: prosFromBreakdown(rationale.breakdown),
      to_verify: toVerifyFromMissing([...(rationale.missing_specialized || []), ...(rationale.missing_general || [])]),
    },
    is_active: r.is_active,
    created_at: r.created_at,
  };
}

export async function fetchSnapshot(): Promise<Snapshot | null> {
  const me = await currentMe();
  if (!me) return null;
  const s = sb();
  const all = <T,>(q: PromiseLike<{ data: T[] | null; error: unknown }>, where: string) =>
    Promise.resolve(q).then(({ data, error }) => { if (error) fail(where, error); return data || []; });

  const [
    profiles, contactsOwn, details, locs, skills, certs, jobs, jobLocs, needs,
    matches, favs, aiProfiles, aiSummaries, notifs,
  ] = await Promise.all([
    all<any>(s.from('profiles').select('*'), 'profiles'),
    all<any>(s.from('contact_details').select('*'), 'contact_details'),
    all<any>(s.from('caregiver_details').select('*'), 'caregiver_details'),
    all<any>(s.from('caregiver_locations').select('*'), 'caregiver_locations'),
    all<any>(s.from('caregiver_case_skills').select('*'), 'caregiver_case_skills'),
    all<any>(s.from('certificates').select('*'), 'certificates'),
    all<any>(s.from('job_posts').select('*').order('created_at', { ascending: false }), 'job_posts'),
    all<any>(s.from('job_post_locations').select('*'), 'job_post_locations'),
    all<any>(s.from('job_post_case_needs').select('*'), 'job_post_case_needs'),
    all<any>(s.from('matches').select('*'), 'matches'),
    all<any>(s.from('favorites').select('*'), 'favorites'),
    all<any>(s.from('ai_worker_profiles').select('*').eq('is_active', true), 'ai_worker_profiles'),
    all<any>(s.from('ai_applicant_summaries').select('*').eq('is_active', true), 'ai_applicant_summaries'),
    all<any>(s.from('notifications').select('*').order('created_at', { ascending: false }).limit(100), 'notifications'),
  ]);

  // caregiver display extras live in caregiver_details.extra_answers; family avatar on job extra_answers
  const detailById: Record<string, any> = Object.fromEntries(details.map((d) => [d.caregiver_id, d]));
  const familyAvatar: Record<string, string> = {};
  jobs.forEach((j) => { if (j.extra_answers?.family_avatar_url) familyAvatar[j.family_id] = j.extra_answers.family_avatar_url; });

  const snap: Snapshot = {
    me,
    contact: null,
    profiles: profiles.map((p) => ({
      id: p.id,
      role: p.role,
      display_name: p.display_name,
      avatar_url: detailById[p.id]?.extra_answers?.avatar_url || familyAvatar[p.id] || null,
      gender: feGender(detailById[p.id]?.gender),
      created_at: p.created_at,
      updated_at: p.updated_at,
    })),
    contacts: {},
    caregiverDetails: {},
    caregiverLocations: {},
    caregiverSkills: {},
    certificates: {},
    jobPosts: jobs.map((j) => ({
      id: j.id,
      family_id: j.family_id,
      patient_description: j.patient_description,
      patient_gender: j.patient_gender,
      patient_age: j.patient_age,
      work_arrangement: j.work_arrangement,
      province: j.province,
      district: j.district || '',
      preferred_caregiver_gender: j.preferred_caregiver_gender,
      expected_wage: j.wage_max ?? j.wage_min ?? null,
      wage_unit: j.wage_unit || 'month',
      start_date: j.start_date,
      extra_answers: j.extra_answers || {},
      status: j.status,
      expires_at: j.expires_at,
      closed_at: j.closed_at,
      created_at: j.created_at,
      updated_at: j.updated_at,
    })),
    jobLocations: {},
    jobNeeds: {},
    matches: matches.map((m) => ({
      id: m.id, job_post_id: m.job_post_id, caregiver_id: m.caregiver_id,
      caregiver_decision: m.caregiver_decision, family_decision: m.family_decision,
      caregiver_decided_at: m.caregiver_decided_at, family_decided_at: m.family_decided_at,
      matched_at: m.matched_at, created_at: m.created_at,
    })),
    favorites: favs.map((f) => ({
      id: `${f.family_id}:${f.caregiver_id}`, family_id: f.family_id, caregiver_id: f.caregiver_id, created_at: f.created_at,
    })),
    aiProfiles: {},
    aiSummaries: {},
    notifications: notifs.map((n) => ({
      id: n.id, user_id: n.user_id, title: n.title, message: n.body || '',
      link_url: NOTIF_LINK[n.type] || null, read_at: n.read_at, line_sent_at: n.line_sent_at, created_at: n.created_at,
    })),
    distances: {},
    candidates: {},
  };

  contactsOwn.forEach((c) => {
    const row: ContactDetails = {
      user_id: c.user_id, phone: c.phone || '', line_id: c.line_id, line_user_id: c.line_user_id,
      created_at: c.updated_at, updated_at: c.updated_at,
    };
    snap.contacts[c.user_id] = row;
    if (c.user_id === me.id) snap.contact = row;
  });

  details.forEach((d) => {
    snap.caregiverDetails[d.caregiver_id] = {
      caregiver_id: d.caregiver_id,
      care_roles: d.care_roles || [],
      work_arrangements: d.work_arrangements || [],
      years_experience: d.years_experience ?? 0,
      expected_wage_min: d.expected_wage_min ?? 0,
      expected_wage_max: d.expected_wage_max ?? 0,
      wage_unit: d.wage_unit || 'month',
      home_province: d.home_province || '',
      home_district: d.home_district || '',
      max_travel_km: d.max_travel_km ?? 20,
      gender: feGender(d.gender),
      age: ageFromBirthYear(d.birth_year),
      avatar_url: d.extra_answers?.avatar_url || null,
      extra_answers: d.extra_answers || {},
      is_visible: d.is_visible,
      created_at: d.created_at,
      updated_at: d.updated_at,
    };
  });
  locs.forEach((l) => {
    snap.caregiverLocations[l.caregiver_id] = {
      caregiver_id: l.caregiver_id, address_text: l.address_text || '', lat: l.lat, lng: l.lng,
      created_at: l.updated_at, updated_at: l.updated_at,
    };
  });
  skills.forEach((k) => {
    const code = toFeCase(k.case_type);
    if (!code) return;
    (snap.caregiverSkills[k.caregiver_id] ||= []).push({
      id: `${k.caregiver_id}:${k.case_type}`, caregiver_id: k.caregiver_id, case_type: code, comfort_level: k.comfort_level,
    });
  });

  // certificate previews: short-lived signed URLs (bucket is private)
  const signed: Record<string, string> = {};
  if (certs.length) {
    const { data } = await s.storage.from('certificates').createSignedUrls(certs.map((c) => c.file_path), 3600);
    (data || []).forEach((d) => { if (d.path && d.signedUrl) signed[d.path] = d.signedUrl; });
  }
  certs.forEach((c) => {
    (snap.certificates[c.caregiver_id] ||= []).push({
      id: c.id, caregiver_id: c.caregiver_id, file_path: c.file_path, file_name: c.title,
      verification_status: c.verification_status, cert_type: certLabel(c.cert_type), issued_by: c.issuer,
      preview_url: signed[c.file_path], created_at: c.created_at,
    });
  });

  jobLocs.forEach((l) => {
    snap.jobLocations[l.job_post_id] = {
      job_post_id: l.job_post_id, address_text: l.address_text || '', lat: l.lat, lng: l.lng,
      created_at: l.updated_at, updated_at: l.updated_at,
    };
  });
  needs.forEach((n) => {
    const code = toFeCase(n.case_type);
    if (!code) return;
    (snap.jobNeeds[n.job_post_id] ||= []).push({
      id: `${n.job_post_id}:${n.case_type}`, job_post_id: n.job_post_id, case_type: code, is_required: n.is_required,
    });
  });

  aiProfiles.forEach((p) => {
    if (!p.caregiver_id) return;
    snap.aiProfiles[p.caregiver_id] = toWorkerProfile(p, detailById[p.caregiver_id]?.extra_answers?.profile_text_override);
  });
  aiSummaries.forEach((r) => { snap.aiSummaries[`${r.job_post_id}:${r.caregiver_id}`] = toSummary(r); });

  // Distances come from SECURITY DEFINER RPCs (private coordinates never reach the browser)
  if (me.role === 'caregiver') {
    const { data, error } = await s.rpc('job_feed_for_me', { p_max_km: null, p_limit: 100 });
    if (error) console.warn('[live] job_feed_for_me', error);
    (data || []).forEach((r: any) => { snap.distances[r.job_post_id] = r.distance_km; });
  } else {
    const myOpen = jobs.filter((j) => j.family_id === me.id && j.status === 'open');
    for (const j of myOpen) {
      const { data, error } = await s.rpc('candidate_caregivers', { p_job_post_id: j.id, p_max_km: null, p_limit: 100 });
      if (error) console.warn('[live] candidate_caregivers', error);
      snap.candidates[j.id] = (data || []).map((r: any) => r.caregiver_id);
      (data || []).forEach((r: any) => { snap.distances[r.caregiver_id] = r.distance_km; });
    }
  }

  // Contact reveal for mutual matches (RPC returns the OTHER party only after matched_at)
  const mutual = matches.filter((m) => m.matched_at);
  await Promise.all(mutual.map(async (m) => {
    const { data } = await s.rpc('get_match_contact', { p_match_id: m.id });
    const c = (data || [])[0];
    if (c) {
      snap.contacts[c.user_id] = {
        user_id: c.user_id, phone: c.phone || '', line_id: c.line_id, line_user_id: null,
        created_at: m.matched_at, updated_at: m.matched_at,
      };
    }
  }));

  return snap;
}

