export interface CaregiverWrite {
  display_name: string;
  phone: string;
  line_id?: string | null;
  avatar_url?: string | null;
  gender?: CaregiverGender;
  age?: number | null;
  home_province: string;
  home_district: string;
  address_text?: string;
  lat?: number;
  lng?: number;
  max_travel_km: number;
  care_roles: string[];
  years_experience: number;
  expected_wage_min: number;
  expected_wage_max: number;
  wage_unit: string;
  work_arrangements: string[];
  skills: { case_type: CaseTypeCode; comfort_level: ComfortLevel }[];
  certificates: { file_name: string; cert_type: string; preview_url: string }[];
  custom_tags?: string[];
}

const CERT_LABEL: Record<string, string> = {
  nurse_aide: 'หลักสูตรพนักงานช่วยการพยาบาล (NA)',
  practical_nurse: 'หลักสูตรผู้ช่วยพยาบาล (PN)',
  caregiver_training: 'หลักสูตรผู้ดูแลผู้สูงอายุ (Caregiver)',
  first_aid: 'การปฐมพยาบาลเบื้องต้น',
  other: 'ใบรับรองอื่นๆ',
};
export const certLabel = (dbType: string) => CERT_LABEL[dbType] || dbType;

/** Free-text / UI certificate type → certificates.cert_type enum. */
export function certTypeToDb(t?: string | null): string {
  const s = (t || '').toLowerCase();
  if (CERT_LABEL[s]) return s;
  if (/practical|\bpn\b|ผู้ช่วยพยาบาล/.test(s)) return 'practical_nurse';
  if (/nurse aide|\bna\b|ช่วยการพยาบาล/.test(s)) return 'nurse_aide';
  if (/first aid|ปฐมพยาบาล|cpr/.test(s)) return 'first_aid';
  if (/caregiver|ผู้ดูแล|ผู้สูงอายุ|อบรม/.test(s)) return 'caregiver_training';
  return 'other';
}

async function uploadCertificate(uid: string, dataUrl: string): Promise<string | null> {
  if (!dataUrl.startsWith('data:')) return null;
  const blob = await (await fetch(dataUrl)).blob();
  const ext = (blob.type.split('/')[1] || 'jpg').replace('jpeg', 'jpg');
  const path = `${uid}/${newId()}.${ext}`;
  const { error } = await sb().storage.from('certificates').upload(path, blob, { contentType: blob.type });
  if (error) { console.warn('[live] certificate upload', error); return null; }
  return path;
}

export async function saveCaregiver(uid: string, p: CaregiverWrite) {
  const s = sb();
  const { data: existing } = await s.from('caregiver_details').select('extra_answers,is_visible').eq('caregiver_id', uid).maybeSingle();
  const min = Math.max(0, Math.round(p.expected_wage_min || 0));
  const max = Math.max(min, Math.round(p.expected_wage_max || 0));

  const det = await s.from('caregiver_details').upsert({
    caregiver_id: uid,
    gender: dbGender(p.gender),
    birth_year: birthYearFromAge(p.age),
    care_roles: p.care_roles,
    years_experience: Math.min(60, Math.max(0, Math.round(p.years_experience || 0))),
    work_arrangements: p.work_arrangements,
    home_province: p.home_province,
    home_district: p.home_district,
    max_travel_km: Math.min(500, Math.max(1, Math.round(p.max_travel_km || 20))),
    expected_wage_min: min || null,
    expected_wage_max: max || null,
    wage_unit: p.wage_unit || 'month',
    extra_answers: { ...(existing?.extra_answers || {}), avatar_url: smallAvatar(p.avatar_url), custom_tags: cleanTags(p.custom_tags) },
    is_visible: existing?.is_visible ?? false,
  });
  if (det.error) fail('caregiver_details', det.error);

  const ll = typeof p.lat === 'number' && typeof p.lng === 'number'
    ? { lat: p.lat, lng: p.lng } : approxLatLng(p.home_province, p.home_district);
  const loc = await s.from('caregiver_locations').upsert({
    caregiver_id: uid,
    address_text: p.address_text || `${p.home_district} ${p.home_province}`,
    lat: ll?.lat ?? null,
    lng: ll?.lng ?? null,
  });
  if (loc.error) fail('caregiver_locations', loc.error);

  const del = await s.from('caregiver_case_skills').delete().eq('caregiver_id', uid);
  if (del.error) fail('caregiver_case_skills delete', del.error);
  if (p.skills.length) {
    const ins = await s.from('caregiver_case_skills').insert(
      p.skills.map((k) => ({ caregiver_id: uid, case_type: toDbCase(k.case_type), comfort_level: k.comfort_level }))
    );
    if (ins.error) fail('caregiver_case_skills', ins.error);
  }

  await s.from('profiles').update({ display_name: p.display_name || 'ผู้ดูแล' }).eq('id', uid);
  await s.from('contact_details').update({ phone: p.phone || null, line_id: p.line_id || null }).eq('user_id', uid);

  // only new uploads (data: URLs) become certificate rows; verification stays 'pending'
  for (const c of p.certificates) {
    const path = await uploadCertificate(uid, c.preview_url || '');
    if (!path) continue;
    await s.from('certificates').insert({
      caregiver_id: uid,
      cert_type: certTypeToDb(c.cert_type),
      title: c.file_name || 'ใบรับรอง',
      file_path: path,
    });
  }
}

export async function setCaregiverVisible(uid: string, visible: boolean) {
  const { error } = await sb().from('caregiver_details').update({ is_visible: visible }).eq('caregiver_id', uid);
  if (error) fail('publish caregiver', error);
}

export async function saveProfileTextEdit(uid: string, aiProfileId: string, newText: string, originalText: string) {
  const s = sb();
  const { data } = await s.from('caregiver_details').select('extra_answers').eq('caregiver_id', uid).maybeSingle();
  await s.from('caregiver_details')
    .update({ extra_answers: { ...(data?.extra_answers || {}), profile_text_override: newText } })
    .eq('caregiver_id', uid);
  if (isUuid(aiProfileId)) {
    await s.from('feedback_corrections').insert({
      user_id: uid, target_type: 'worker_profile', target_id: aiProfileId,
      original_text: originalText, corrected_text: newText,
    });
  }
}

export interface JobWrite {
  id: string;
  patient_description: string;
  patient_gender?: string | null;
  patient_age?: number | null;
  work_arrangement: string;
  province: string;
  district: string;
  address_text?: string;
  lat?: number;
  lng?: number;
  preferred_caregiver_gender: string;
  expected_wage: number | null;
  wage_unit: string;
  start_date: string | null;
  cases: { case_type: CaseTypeCode; is_required: boolean }[];
  status: 'draft' | 'open';
  display_name?: string;
  phone?: string;
  line_id?: string;
  avatar_url?: string | null;
  custom_tags?: string[];
}

const jobTitle = (d: string) => {
  const t = (d || '').replace(/\s+/g, ' ').trim();
  return (t.length > 60 ? `${t.slice(0, 57)}...` : t) || 'หาผู้ดูแลผู้ป่วย';
};

/** Insert a new job, or (isUpdate) overwrite the family's existing one — the UI has one job per family. */
export async function saveJob(uid: string, p: JobWrite, isUpdate = false) {
  const s = sb();
  const row = {
    title: jobTitle(p.patient_description),
    patient_description: p.patient_description || '-',
    patient_age: typeof p.patient_age === 'number' && p.patient_age >= 0 && p.patient_age <= 120 ? p.patient_age : null,
    patient_gender: p.patient_gender === 'female' || p.patient_gender === 'male' ? p.patient_gender : null,
    work_arrangement: p.work_arrangement,
    province: p.province || 'กรุงเทพมหานคร',
    district: p.district || null,
    start_date: p.start_date || null,
    wage_min: null,
    wage_max: p.expected_wage ?? null,
    wage_unit: p.wage_unit || 'month',
    preferred_caregiver_gender: p.preferred_caregiver_gender || 'any',
    extra_answers: { family_avatar_url: smallAvatar(p.avatar_url), custom_tags: cleanTags(p.custom_tags) },
    status: p.status,
  };
  const jr = isUpdate
    ? await s.from('job_posts').update(row).eq('id', p.id)
    : await s.from('job_posts').insert({ id: p.id, family_id: uid, ...row });
  if (jr.error) fail('job_posts', jr.error);

  const ll = typeof p.lat === 'number' && typeof p.lng === 'number'
    ? { lat: p.lat, lng: p.lng } : approxLatLng(p.province, p.district);
  const loc = await s.from('job_post_locations').upsert({
    job_post_id: p.id,
    address_text: p.address_text || `${p.district} ${p.province}`,
    lat: ll?.lat ?? null,
    lng: ll?.lng ?? null,
  });
  if (loc.error) fail('job_post_locations', loc.error);

  if (isUpdate) {
    const del = await s.from('job_post_case_needs').delete().eq('job_post_id', p.id);
    if (del.error) fail('job_post_case_needs delete', del.error);
  }
  const seen = new Set<string>();
  const needs = p.cases
    .map((c) => ({ job_post_id: p.id, case_type: toDbCase(c.case_type), is_required: c.is_required }))
    .filter((n) => (seen.has(n.case_type) ? false : (seen.add(n.case_type), true)));
  if (needs.length) {
    const r = await s.from('job_post_case_needs').insert(needs);
    if (r.error) fail('job_post_case_needs', r.error);
  }

  if (p.display_name) await s.from('profiles').update({ display_name: p.display_name }).eq('id', uid);
  if (p.phone) await s.from('contact_details').update({ phone: p.phone, line_id: p.line_id || null }).eq('user_id', uid);
}

export async function updateJob(jobId: string, patch: { patient_description?: string; status?: string }) {
  const row: Record<string, unknown> = { ...patch };
  if (patch.patient_description) row.title = jobTitle(patch.patient_description);
  const { error } = await sb().from('job_posts').update(row).eq('id', jobId);
  if (error) fail('update job', error);
}

export async function updateFamilyContact(uid: string, p: { display_name?: string; phone?: string; line_id?: string | null }) {
  if (p.display_name) await sb().from('profiles').update({ display_name: p.display_name }).eq('id', uid);
  if (p.phone !== undefined || p.line_id !== undefined) {
    await sb().from('contact_details').update({ phone: p.phone || null, line_id: p.line_id || null }).eq('user_id', uid);
  }
}

/** Each side only writes its own decision column; the DB trigger sets matched_at. */
export async function swipe(jobPostId: string, caregiverId: string, side: 'caregiver' | 'family', decision: 'like' | 'pass' | null) {
  const s = sb();
  const col = side === 'caregiver' ? 'caregiver_decision' : 'family_decision';
  const { data: existing } = await s.from('matches').select('id').eq('job_post_id', jobPostId).eq('caregiver_id', caregiverId).maybeSingle();
  const res = existing
    ? await s.from('matches').update({ [col]: decision }).eq('id', existing.id)
    : await s.from('matches').insert({ job_post_id: jobPostId, caregiver_id: caregiverId, [col]: decision });
  if (res.error) fail('swipe', res.error);
}

export async function setFavorite(familyId: string, caregiverId: string, on: boolean) {
  const s = sb();
  const res = on
    ? await s.from('favorites').insert({ family_id: familyId, caregiver_id: caregiverId })
    : await s.from('favorites').delete().eq('family_id', familyId).eq('caregiver_id', caregiverId);
  if (res.error && !String(res.error.message).includes('duplicate')) fail('favorite', res.error);
}

export async function markRead(notifId: string) {
  if (!isUuid(notifId)) return;
  await sb().from('notifications').update({ read_at: nowIso() }).eq('id', notifId);
}

export async function savePlatformReview(uid: string, r: { ease: number; ui: number; ai: number; comment: string | null }) {
  const clamp = (n: number) => Math.min(5, Math.max(1, Math.round(n || 3)));
  const row = { ease_of_use: clamp(r.ease), ui_design: clamp(r.ui), ai_summary_quality: clamp(r.ai), comment: r.comment };
  const ins = await sb().from('platform_reviews').insert({ user_id: uid, ...row });
  if (ins.error) {
    const up = await sb().from('platform_reviews').update(row).eq('user_id', uid);
    if (up.error) fail('platform review', up.error);
  }
}

